/** Read a completed Lighthouse report so an interrupted matrix can resume safely. */
function readCompletedReport(reportPath) {
  try {
    const report = JSON.parse(readFileSync(reportPath, 'utf8'));
    return report.lighthouseVersion === '13.4.1' ? report : null;
  } catch {
    return null;
  }
}

/** Run Lighthouse in a unique Chrome profile and keep the raw JSON result. */
function runLighthouse({ url, reportPath, extraArguments, categories }) {
  const existingReport = readCompletedReport(reportPath);
  if (existingReport) return existingReport;

// Function to check if the referrer is Google
function isGoogleSource() {
    return (
        referringDomain && referringDomain.includes('google.com')
    );
}

// Cache viewport-space centres so pointer movement never reads layout in a tight loop.
const measureLenders = () => {
  lenderMetrics = Array.from(lenderButtonRefs.current.entries()).map(([slug, element]) => {
    const rect = element.getBoundingClientRect()

    return {
      slug,
      element,
      x: rect.left + rect.width / 2,
      y: rect.top + rect.height / 2,
    }
  })

  metricsAreStale = false
}

const closeMobileMenu = () => {
  if (!dialog.open || panel.hasAttribute('data-leave')) return

  clearTransitionTimer()
  panel.removeAttribute('data-enter')
  panel.setAttribute('data-leave', '')
  panel.setAttribute('data-closed', '')
  transitionTimer = window.setTimeout(finishClose, 170)
}

const openMobileMenu = () => {
  if (dialog.open) return

  clearTransitionTimer()
  panel.removeAttribute('data-leave')
  panel.setAttribute('data-enter', '')
  panel.setAttribute('data-closed', '')
  dialog.showModal()
  openButton.setAttribute('aria-expanded', 'true')

  enterFrame = window.requestAnimationFrame(() => {
    settleFrame = window.requestAnimationFrame(() => {
      panel.removeAttribute('data-closed')
      transitionTimer = window.setTimeout(() => {
        panel.removeAttribute('data-enter')
        transitionTimer = null
      }, 280)
    })
  })
